-- Patchnotes 0.8.8, 0.8.9 and 0.9.0: final content for the 0.9.0 release.
--
-- 0.8.8 and 0.8.9 were tagged or seeded but never published: the last released version is 0.8.7,
-- so an upgrading instance crosses three versions and sees all three notes. Each one therefore
-- carries what actually shipped in it, rather than everything being piled into 0.9.0.
--
-- UPDATE then INSERT per version: an instance that ran the August migrations already holds a row,
-- a fresh install holds none. Both end on the same content, and re-running is a no-op.

UPDATE "Patchnote"
SET "type" = 'patch', "date" = '2026-08-06T12:00:00.000Z', "titleEn" = 'Smaller, hardened image and a tighter API', "titleFr" = 'Image plus légère et durcie, API mieux protégée', "entries" = '[{"type":"fix","titleEn":"The Seerr-compatible API is now rate limited","titleFr":"L''API compatible Seerr est désormais limitée en débit","descEn":"/api/v1 is public by design so third-party apps can reach it. It now caps requests per minute, so an unauthenticated flood can no longer keep the server busy. Two URL-processing regexes that became expensive on certain inputs were replaced at the same time.","descFr":"L''API /api/v1 est publique par conception, pour que les applications tierces puissent s''y connecter. Elle plafonne désormais le nombre de requêtes par minute : un flot non authentifié ne peut plus occuper le serveur. Deux expressions régulières de traitement d''URL, coûteuses sur certaines entrées, ont été remplacées au passage."},{"type":"perf","titleEn":"Lighter, hardened container image","titleFr":"Image conteneur plus légère et durcie","descEn":"The image moved to a hardened Wolfi base and dropped everything it never loads: 635 MB down to 520 MB. Dependency install scripts are now denied unless explicitly allowed, so a compromised transitive dependency cannot run anything during the build.","descFr":"L''image passe sur une base Wolfi durcie et perd tout ce qu''elle ne charge jamais : de 635 Mo à 520 Mo. Les scripts d''installation des dépendances sont désormais interdits sauf autorisation explicite, si bien qu''une dépendance transitive compromise ne peut rien exécuter pendant la construction."},{"type":"fix","titleEn":"Runtime dependencies installed from a committed lockfile","titleFr":"Dépendances runtime installées depuis un lockfile versionné","descEn":"The runtime stage resolved its dependency ranges from scratch on every build, so a version published minutes earlier could walk into the image. It now installs the exact reviewed tree with npm ci, and fails outright if the manifest and the lockfile drift apart.","descFr":"L''étape runtime re-résolvait ses plages de dépendances à chaque construction : une version publiée quelques minutes plus tôt pouvait entrer dans l''image. Elle installe désormais l''arbre exact validé avec npm ci, et échoue franchement si le manifeste et le lockfile divergent."},{"type":"fix","titleEn":"Dependencies brought up to date","titleFr":"Dépendances remises à jour","descEn":"Cleared 12 of 14 security findings, including a critical one in the archive library and an authorization bypass in the static file handler. The two left are documented as not reachable in Oscarr.","descFr":"12 des 14 alertes de sécurité sont résolues, dont une critique dans la bibliothèque d''archives et un contournement d''autorisation dans le gestionnaire de fichiers statiques. Les deux restantes sont documentées comme non atteignables dans Oscarr."}]'
WHERE "version" = '0.8.8';

INSERT INTO "Patchnote" ("version", "type", "date", "titleEn", "titleFr", "entries") VALUES
('0.8.8', 'patch', '2026-08-06T12:00:00.000Z', 'Smaller, hardened image and a tighter API', 'Image plus légère et durcie, API mieux protégée', '[{"type":"fix","titleEn":"The Seerr-compatible API is now rate limited","titleFr":"L''API compatible Seerr est désormais limitée en débit","descEn":"/api/v1 is public by design so third-party apps can reach it. It now caps requests per minute, so an unauthenticated flood can no longer keep the server busy. Two URL-processing regexes that became expensive on certain inputs were replaced at the same time.","descFr":"L''API /api/v1 est publique par conception, pour que les applications tierces puissent s''y connecter. Elle plafonne désormais le nombre de requêtes par minute : un flot non authentifié ne peut plus occuper le serveur. Deux expressions régulières de traitement d''URL, coûteuses sur certaines entrées, ont été remplacées au passage."},{"type":"perf","titleEn":"Lighter, hardened container image","titleFr":"Image conteneur plus légère et durcie","descEn":"The image moved to a hardened Wolfi base and dropped everything it never loads: 635 MB down to 520 MB. Dependency install scripts are now denied unless explicitly allowed, so a compromised transitive dependency cannot run anything during the build.","descFr":"L''image passe sur une base Wolfi durcie et perd tout ce qu''elle ne charge jamais : de 635 Mo à 520 Mo. Les scripts d''installation des dépendances sont désormais interdits sauf autorisation explicite, si bien qu''une dépendance transitive compromise ne peut rien exécuter pendant la construction."},{"type":"fix","titleEn":"Runtime dependencies installed from a committed lockfile","titleFr":"Dépendances runtime installées depuis un lockfile versionné","descEn":"The runtime stage resolved its dependency ranges from scratch on every build, so a version published minutes earlier could walk into the image. It now installs the exact reviewed tree with npm ci, and fails outright if the manifest and the lockfile drift apart.","descFr":"L''étape runtime re-résolvait ses plages de dépendances à chaque construction : une version publiée quelques minutes plus tôt pouvait entrer dans l''image. Elle installe désormais l''arbre exact validé avec npm ci, et échoue franchement si le manifeste et le lockfile divergent."},{"type":"fix","titleEn":"Dependencies brought up to date","titleFr":"Dépendances remises à jour","descEn":"Cleared 12 of 14 security findings, including a critical one in the archive library and an authorization bypass in the static file handler. The two left are documented as not reachable in Oscarr.","descFr":"12 des 14 alertes de sécurité sont résolues, dont une critique dans la bibliothèque d''archives et un contournement d''autorisation dans le gestionnaire de fichiers statiques. Les deux restantes sont documentées comme non atteignables dans Oscarr."}]')
ON CONFLICT ("version") DO NOTHING;

UPDATE "Patchnote"
SET "type" = 'patch', "date" = '2026-08-15T12:00:00.000Z', "titleEn" = 'Users can recover their own password', "titleFr" = 'Les utilisateurs peuvent récupérer leur mot de passe', "entries" = '[{"type":"feat","titleEn":"Password recovery for local accounts","titleFr":"Réinitialisation du mot de passe pour les comptes locaux","descEn":"Local Oscarr accounts can now reset their password by email instead of asking an administrator. The shared mail configuration supports SMTP or Resend, and email notifications use the same transport, so mail credentials are configured once. Optional, and only for accounts using an Oscarr password: Plex, Jellyfin, Emby and Discord users keep authenticating through their provider.","descFr":"Les comptes locaux Oscarr peuvent désormais réinitialiser leur mot de passe par e-mail au lieu de solliciter un administrateur. La configuration mail commune prend en charge SMTP ou Resend, et les notifications e-mail utilisent le même transport : les identifiants d''envoi ne sont donc à renseigner qu''une fois. Optionnel, et réservé aux comptes disposant d''un mot de passe Oscarr : les utilisateurs Plex, Jellyfin, Emby et Discord continuent de passer par leur fournisseur."}]'
WHERE "version" = '0.8.9';

INSERT INTO "Patchnote" ("version", "type", "date", "titleEn", "titleFr", "entries") VALUES
('0.8.9', 'patch', '2026-08-15T12:00:00.000Z', 'Users can recover their own password', 'Les utilisateurs peuvent récupérer leur mot de passe', '[{"type":"feat","titleEn":"Password recovery for local accounts","titleFr":"Réinitialisation du mot de passe pour les comptes locaux","descEn":"Local Oscarr accounts can now reset their password by email instead of asking an administrator. The shared mail configuration supports SMTP or Resend, and email notifications use the same transport, so mail credentials are configured once. Optional, and only for accounts using an Oscarr password: Plex, Jellyfin, Emby and Discord users keep authenticating through their provider.","descFr":"Les comptes locaux Oscarr peuvent désormais réinitialiser leur mot de passe par e-mail au lieu de solliciter un administrateur. La configuration mail commune prend en charge SMTP ou Resend, et les notifications e-mail utilisent le même transport : les identifiants d''envoi ne sont donc à renseigner qu''une fois. Optionnel, et réservé aux comptes disposant d''un mot de passe Oscarr : les utilisateurs Plex, Jellyfin, Emby et Discord continuent de passer par leur fournisseur."}]')
ON CONFLICT ("version") DO NOTHING;

UPDATE "Patchnote"
SET "type" = 'minor', "date" = '2026-09-02T12:00:00.000Z', "titleEn" = 'Reliability, security, media availability and setup quality', "titleFr" = 'Fiabilité, sécurité, disponibilité des médias et qualité d''installation', "entries" = '[{"type":"feat","titleEn":"The last credentials stored in the clear are now encrypted","titleFr":"Les derniers identifiants stockés en clair sont chiffrés","descEn":"Service credentials have been encrypted since 0.8.1, but notification provider settings, authentication provider configs and the instance API key still sat in the clear. The sensitive-field check could not split camelCase either, so clientSecret, botToken and webhookUrl read as harmless even where encryption was applied. Existing rows are swept on this start, with nothing to do on your side.","descFr":"Les identifiants de service sont chiffrés depuis la 0.8.1, mais les réglages des fournisseurs de notification, les configurations d''authentification et la clé d''API de l''instance restaient en clair. La détection des champs sensibles ne savait pas non plus découper le camelCase, si bien que clientSecret, botToken et webhookUrl passaient pour anodins même là où le chiffrement s''appliquait. Les enregistrements existants sont repris à ce démarrage, sans rien à faire de votre côté."},{"type":"feat","titleEn":"Choose what actually decides that a title is available","titleFr":"Choisissez ce qui décide réellement qu''un titre est disponible","descEn":"Availability can now be decided by the service that best represents your setup, independently for movies and TV shows. It used to rest on what the *arr reported, which does not always match what a user can actually watch: on a real library of 3,626 titles, 76 differed. That is 2.1%. The change applies immediately, with no new sync. A new Imported state also covers media that is downloaded but not yet visible on the media server.","descFr":"La disponibilité peut désormais être décidée par le service qui correspond le mieux à votre installation, indépendamment pour les films et les séries. Elle reposait jusqu''ici sur l''état remonté par le *arr, qui ne correspond pas toujours à ce que l''utilisateur peut réellement regarder : sur une bibliothèque réelle de 3 626 titres, 76 différaient, soit 2,1 %. Le changement s''applique immédiatement, sans nouvelle synchronisation. Un nouvel état Importé couvre par ailleurs un média téléchargé mais pas encore visible sur le serveur multimédia."},{"type":"fix","titleEn":"Request the seasons a series is still missing","titleFr":"Demandez les saisons encore manquantes d''une série","descEn":"A series is no longer treated as fully available just because Sonarr reports 100% of its monitored episodes as downloaded. If season 1 is there but seasons 2 and 3 are missing or unmonitored, users can request them normally.","descFr":"Une série n''est plus considérée comme entièrement disponible au seul motif que Sonarr annonce 100 % de ses épisodes surveillés téléchargés. Si la saison 1 est là mais que les saisons 2 et 3 manquent ou ne sont pas surveillées, les utilisateurs peuvent les demander normalement."},{"type":"fix","titleEn":"A smoother installation","titleFr":"Une installation plus fluide","descEn":"Refreshing the setup wizard no longer creates duplicate Radarr/Sonarr services, and a resumed setup reloads what is already configured without exposing its secrets. Finishing the wizard no longer bounces between /install and /login. Entering a Radarr URL in a Sonarr form, or the reverse, is now detected instead of passing the connection test. The first administrator is created through the protected installation flow.","descFr":"Rafraîchir l''assistant d''installation ne crée plus de doublons de services Radarr/Sonarr, et une installation reprise recharge ce qui est déjà configuré sans exposer les secrets. Terminer l''assistant ne rebondit plus entre /install et /login. Renseigner une URL Radarr dans un formulaire Sonarr, ou l''inverse, est désormais détecté au lieu de réussir le test de connexion. Le premier administrateur est créé via le parcours d''installation protégé."},{"type":"feat","titleEn":"Plugin archives are verified before they are extracted","titleFr":"Les archives de plugins sont vérifiées avant extraction","descEn":"Oscarr now checks the .sha256 checksum published with a plugin release before unpacking it, and a mismatch blocks the installation. This protects against a download asset replaced by accident or on purpose. It is a checksum and not a cryptographic signature, so it cannot protect against the release itself being compromised at the source.","descFr":"Oscarr vérifie désormais l''empreinte .sha256 publiée avec une version de plugin avant de la déballer, et une empreinte différente bloque l''installation. Cela protège contre une archive remplacée par accident ou volontairement. Il s''agit d''une empreinte et non d''une signature cryptographique : elle ne protège pas si la version elle-même est compromise à la source."},{"type":"feat","titleEn":"Clearer plugin management","titleFr":"Gestion des plugins plus claire","descEn":"A freshly installed plugin stays disabled until its permissions have been reviewed. Oscarr now says so and offers a direct Review & enable action. Update dialogs show each newly requested capability once, with its explanation when the manifest provides one. Admins can also open a title directly in the Radarr or Sonarr Manager plugin from its Oscarr page.","descFr":"Un plugin fraîchement installé reste désactivé tant que ses permissions n''ont pas été vérifiées. Oscarr l''explique désormais et propose directement l''action Vérifier et activer. Les fenêtres de mise à jour affichent chaque nouvelle capacité demandée une seule fois, avec son explication lorsque le manifeste en fournit une. Les administrateurs peuvent aussi ouvrir un titre directement dans le plugin Radarr ou Sonarr Manager depuis sa fiche Oscarr."},{"type":"fix","titleEn":"Safer backup restores","titleFr":"Restaurations de sauvegardes plus sûres","descEn":"Restoring a backup from an older Oscarr now applies the database migrations the current version needs, and falls back to the safety copy if they fail rather than leaving an incompatible database in place. Two restores can no longer run at once and overwrite each other staged files. A restore that includes plugin data asks for a restart so plugin settings, routes and jobs reload correctly. Tested on a real 4,862-title database: restore and migration in 0.4 seconds, data intact, SQLite integrity check OK.","descFr":"Restaurer une sauvegarde issue d''un Oscarr plus ancien applique désormais les migrations dont la version actuelle a besoin, et revient à la copie de sécurité si elles échouent plutôt que de laisser une base incompatible en place. Deux restaurations ne peuvent plus s''exécuter en même temps et écraser leurs fichiers temporaires. Une restauration contenant des données de plugins demande un redémarrage pour que leurs réglages, routes et tâches se rechargent correctement. Testé sur une base réelle de 4 862 titres : restauration et migration en 0,4 seconde, données intactes, contrôle d''intégrité SQLite OK."},{"type":"fix","titleEn":"More reliable requests","titleFr":"Des demandes plus fiables","descEn":"Approving a request now claims it atomically before contacting Radarr or Sonarr, so two administrators approving at the same moment can no longer send the same title twice. Availability notifications collect their recipients before the state transition, which stops them from silently disappearing.","descFr":"Approuver une demande la réserve désormais de manière atomique avant de contacter Radarr ou Sonarr : deux administrateurs qui valident au même moment ne peuvent plus envoyer deux fois le même titre. Les notifications de disponibilité déterminent leurs destinataires avant le changement d''état, ce qui les empêche de disparaître silencieusement."},{"type":"fix","titleEn":"Large Seerr imports go through","titleFr":"Les gros imports Seerr passent","descEn":"Migrations from Seerr are no longer cut short by an arbitrary five-minute deadline. Defaults are now 200,000 rows and 5,000 pages, adjustable with SEERR_IMPORT_MAX_ROWS and SEERR_IMPORT_MAX_PAGES. Each request keeps its own timeout, so a source that stops responding cannot hang the import, and errors report how many rows had already been retrieved.","descFr":"Les migrations depuis Seerr ne sont plus interrompues par une limite arbitraire de cinq minutes. Les valeurs par défaut passent à 200 000 lignes et 5 000 pages, ajustables avec SEERR_IMPORT_MAX_ROWS et SEERR_IMPORT_MAX_PAGES. Chaque requête conserve son propre délai d''attente, donc une source qui cesse de répondre ne peut pas bloquer l''import, et les erreurs indiquent le nombre de lignes déjà récupérées."},{"type":"fix","titleEn":"Reverse proxy and HTTPS","titleFr":"Reverse proxy et HTTPS","descEn":"TRUST_PROXY is now validated: a malformed value falls back to the documented default instead of crashing startup and leaving the container restarting in a loop. FORCE_HTTPS also marks the session cookie as Secure, including where TLS terminates at the proxy. The Docker Compose example documents TRUST_PROXY, FORCE_HTTPS and COOKIE_SECURE. Behind a proxy, setting TRUST_PROXY matters, or every client appears to come from the same address and shares one rate-limit bucket.","descFr":"TRUST_PROXY est désormais validé : une valeur incorrecte retombe sur la valeur par défaut documentée au lieu de faire échouer le démarrage et de laisser le conteneur redémarrer en boucle. FORCE_HTTPS marque aussi le cookie de session comme Secure, y compris quand le TLS se termine au proxy. L''exemple Docker Compose documente TRUST_PROXY, FORCE_HTTPS et COOKIE_SECURE. Derrière un proxy, renseigner TRUST_PROXY compte, sinon tous les clients semblent venir de la même adresse et partagent la même limite de requêtes."},{"type":"perf","titleEn":"Faster first load","titleFr":"Premier chargement plus rapide","descEn":"Pages are fetched as you navigate to them instead of shipping almost the whole application in the initial bundle: the critical download goes from 277 kB to 242 kB gzipped. Home and Login stay immediately available. Browser caching between Oscarr updates improves as a side effect, since changing one page no longer invalidates everything.","descFr":"Les pages sont récupérées au moment où vous les ouvrez au lieu d''embarquer presque toute l''application dès le premier affichage : le téléchargement critique passe de 277 ko à 242 ko compressés. L''accueil et la connexion restent disponibles immédiatement. Le cache du navigateur entre deux mises à jour s''en trouve amélioré, puisque modifier une page n''invalide plus l''ensemble."},{"type":"fix","titleEn":"The update banner no longer points at an older version","titleFr":"La bannière de mise à jour ne renvoie plus vers une version antérieure","descEn":"The check compared version numbers as plain text, so any difference, including an older published version, was announced as an update. Versions are now compared as versions.","descFr":"La vérification comparait les numéros de version comme du texte : tout écart, y compris une version publiée plus ancienne, était annoncé comme une mise à jour. Les versions sont désormais comparées en tant que versions."},{"type":"other","titleEn":"Smaller fixes and groundwork","titleFr":"Correctifs et travaux de fond","descEn":"The instance API key is encrypted like every other credential. NSFW keywords are cached instead of being re-read on every search. The dashboard widget picker gained keyboard navigation and proper focus handling. Folder routing rules, multi-instance ownership and quality-option changes got dedicated automated coverage, and Oscarr now carries 186 automated tests, up from 147. Dependency updates arrive weekly, grouped, with a cooldown before a freshly published version is proposed, and CI rejects any critical advisory.","descFr":"La clé d''API de l''instance est chiffrée comme tout autre identifiant. Les mots-clés NSFW sont mis en cache au lieu d''être relus à chaque recherche. Le sélecteur de widgets du tableau de bord gagne la navigation au clavier et une gestion correcte du focus. Les règles de routage de dossiers, la propriété multi-instances et les changements d''option de qualité disposent de tests automatisés dédiés, et Oscarr compte désormais 186 tests automatisés contre 147. Les mises à jour de dépendances arrivent chaque semaine, groupées, avec un délai avant qu''une version fraîchement publiée soit proposée, et la CI rejette toute alerte critique."}]'
WHERE "version" = '0.9.0';

INSERT INTO "Patchnote" ("version", "type", "date", "titleEn", "titleFr", "entries") VALUES
('0.9.0', 'minor', '2026-09-02T12:00:00.000Z', 'Reliability, security, media availability and setup quality', 'Fiabilité, sécurité, disponibilité des médias et qualité d''installation', '[{"type":"feat","titleEn":"The last credentials stored in the clear are now encrypted","titleFr":"Les derniers identifiants stockés en clair sont chiffrés","descEn":"Service credentials have been encrypted since 0.8.1, but notification provider settings, authentication provider configs and the instance API key still sat in the clear. The sensitive-field check could not split camelCase either, so clientSecret, botToken and webhookUrl read as harmless even where encryption was applied. Existing rows are swept on this start, with nothing to do on your side.","descFr":"Les identifiants de service sont chiffrés depuis la 0.8.1, mais les réglages des fournisseurs de notification, les configurations d''authentification et la clé d''API de l''instance restaient en clair. La détection des champs sensibles ne savait pas non plus découper le camelCase, si bien que clientSecret, botToken et webhookUrl passaient pour anodins même là où le chiffrement s''appliquait. Les enregistrements existants sont repris à ce démarrage, sans rien à faire de votre côté."},{"type":"feat","titleEn":"Choose what actually decides that a title is available","titleFr":"Choisissez ce qui décide réellement qu''un titre est disponible","descEn":"Availability can now be decided by the service that best represents your setup, independently for movies and TV shows. It used to rest on what the *arr reported, which does not always match what a user can actually watch: on a real library of 3,626 titles, 76 differed. That is 2.1%. The change applies immediately, with no new sync. A new Imported state also covers media that is downloaded but not yet visible on the media server.","descFr":"La disponibilité peut désormais être décidée par le service qui correspond le mieux à votre installation, indépendamment pour les films et les séries. Elle reposait jusqu''ici sur l''état remonté par le *arr, qui ne correspond pas toujours à ce que l''utilisateur peut réellement regarder : sur une bibliothèque réelle de 3 626 titres, 76 différaient, soit 2,1 %. Le changement s''applique immédiatement, sans nouvelle synchronisation. Un nouvel état Importé couvre par ailleurs un média téléchargé mais pas encore visible sur le serveur multimédia."},{"type":"fix","titleEn":"Request the seasons a series is still missing","titleFr":"Demandez les saisons encore manquantes d''une série","descEn":"A series is no longer treated as fully available just because Sonarr reports 100% of its monitored episodes as downloaded. If season 1 is there but seasons 2 and 3 are missing or unmonitored, users can request them normally.","descFr":"Une série n''est plus considérée comme entièrement disponible au seul motif que Sonarr annonce 100 % de ses épisodes surveillés téléchargés. Si la saison 1 est là mais que les saisons 2 et 3 manquent ou ne sont pas surveillées, les utilisateurs peuvent les demander normalement."},{"type":"fix","titleEn":"A smoother installation","titleFr":"Une installation plus fluide","descEn":"Refreshing the setup wizard no longer creates duplicate Radarr/Sonarr services, and a resumed setup reloads what is already configured without exposing its secrets. Finishing the wizard no longer bounces between /install and /login. Entering a Radarr URL in a Sonarr form, or the reverse, is now detected instead of passing the connection test. The first administrator is created through the protected installation flow.","descFr":"Rafraîchir l''assistant d''installation ne crée plus de doublons de services Radarr/Sonarr, et une installation reprise recharge ce qui est déjà configuré sans exposer les secrets. Terminer l''assistant ne rebondit plus entre /install et /login. Renseigner une URL Radarr dans un formulaire Sonarr, ou l''inverse, est désormais détecté au lieu de réussir le test de connexion. Le premier administrateur est créé via le parcours d''installation protégé."},{"type":"feat","titleEn":"Plugin archives are verified before they are extracted","titleFr":"Les archives de plugins sont vérifiées avant extraction","descEn":"Oscarr now checks the .sha256 checksum published with a plugin release before unpacking it, and a mismatch blocks the installation. This protects against a download asset replaced by accident or on purpose. It is a checksum and not a cryptographic signature, so it cannot protect against the release itself being compromised at the source.","descFr":"Oscarr vérifie désormais l''empreinte .sha256 publiée avec une version de plugin avant de la déballer, et une empreinte différente bloque l''installation. Cela protège contre une archive remplacée par accident ou volontairement. Il s''agit d''une empreinte et non d''une signature cryptographique : elle ne protège pas si la version elle-même est compromise à la source."},{"type":"feat","titleEn":"Clearer plugin management","titleFr":"Gestion des plugins plus claire","descEn":"A freshly installed plugin stays disabled until its permissions have been reviewed. Oscarr now says so and offers a direct Review & enable action. Update dialogs show each newly requested capability once, with its explanation when the manifest provides one. Admins can also open a title directly in the Radarr or Sonarr Manager plugin from its Oscarr page.","descFr":"Un plugin fraîchement installé reste désactivé tant que ses permissions n''ont pas été vérifiées. Oscarr l''explique désormais et propose directement l''action Vérifier et activer. Les fenêtres de mise à jour affichent chaque nouvelle capacité demandée une seule fois, avec son explication lorsque le manifeste en fournit une. Les administrateurs peuvent aussi ouvrir un titre directement dans le plugin Radarr ou Sonarr Manager depuis sa fiche Oscarr."},{"type":"fix","titleEn":"Safer backup restores","titleFr":"Restaurations de sauvegardes plus sûres","descEn":"Restoring a backup from an older Oscarr now applies the database migrations the current version needs, and falls back to the safety copy if they fail rather than leaving an incompatible database in place. Two restores can no longer run at once and overwrite each other staged files. A restore that includes plugin data asks for a restart so plugin settings, routes and jobs reload correctly. Tested on a real 4,862-title database: restore and migration in 0.4 seconds, data intact, SQLite integrity check OK.","descFr":"Restaurer une sauvegarde issue d''un Oscarr plus ancien applique désormais les migrations dont la version actuelle a besoin, et revient à la copie de sécurité si elles échouent plutôt que de laisser une base incompatible en place. Deux restaurations ne peuvent plus s''exécuter en même temps et écraser leurs fichiers temporaires. Une restauration contenant des données de plugins demande un redémarrage pour que leurs réglages, routes et tâches se rechargent correctement. Testé sur une base réelle de 4 862 titres : restauration et migration en 0,4 seconde, données intactes, contrôle d''intégrité SQLite OK."},{"type":"fix","titleEn":"More reliable requests","titleFr":"Des demandes plus fiables","descEn":"Approving a request now claims it atomically before contacting Radarr or Sonarr, so two administrators approving at the same moment can no longer send the same title twice. Availability notifications collect their recipients before the state transition, which stops them from silently disappearing.","descFr":"Approuver une demande la réserve désormais de manière atomique avant de contacter Radarr ou Sonarr : deux administrateurs qui valident au même moment ne peuvent plus envoyer deux fois le même titre. Les notifications de disponibilité déterminent leurs destinataires avant le changement d''état, ce qui les empêche de disparaître silencieusement."},{"type":"fix","titleEn":"Large Seerr imports go through","titleFr":"Les gros imports Seerr passent","descEn":"Migrations from Seerr are no longer cut short by an arbitrary five-minute deadline. Defaults are now 200,000 rows and 5,000 pages, adjustable with SEERR_IMPORT_MAX_ROWS and SEERR_IMPORT_MAX_PAGES. Each request keeps its own timeout, so a source that stops responding cannot hang the import, and errors report how many rows had already been retrieved.","descFr":"Les migrations depuis Seerr ne sont plus interrompues par une limite arbitraire de cinq minutes. Les valeurs par défaut passent à 200 000 lignes et 5 000 pages, ajustables avec SEERR_IMPORT_MAX_ROWS et SEERR_IMPORT_MAX_PAGES. Chaque requête conserve son propre délai d''attente, donc une source qui cesse de répondre ne peut pas bloquer l''import, et les erreurs indiquent le nombre de lignes déjà récupérées."},{"type":"fix","titleEn":"Reverse proxy and HTTPS","titleFr":"Reverse proxy et HTTPS","descEn":"TRUST_PROXY is now validated: a malformed value falls back to the documented default instead of crashing startup and leaving the container restarting in a loop. FORCE_HTTPS also marks the session cookie as Secure, including where TLS terminates at the proxy. The Docker Compose example documents TRUST_PROXY, FORCE_HTTPS and COOKIE_SECURE. Behind a proxy, setting TRUST_PROXY matters, or every client appears to come from the same address and shares one rate-limit bucket.","descFr":"TRUST_PROXY est désormais validé : une valeur incorrecte retombe sur la valeur par défaut documentée au lieu de faire échouer le démarrage et de laisser le conteneur redémarrer en boucle. FORCE_HTTPS marque aussi le cookie de session comme Secure, y compris quand le TLS se termine au proxy. L''exemple Docker Compose documente TRUST_PROXY, FORCE_HTTPS et COOKIE_SECURE. Derrière un proxy, renseigner TRUST_PROXY compte, sinon tous les clients semblent venir de la même adresse et partagent la même limite de requêtes."},{"type":"perf","titleEn":"Faster first load","titleFr":"Premier chargement plus rapide","descEn":"Pages are fetched as you navigate to them instead of shipping almost the whole application in the initial bundle: the critical download goes from 277 kB to 242 kB gzipped. Home and Login stay immediately available. Browser caching between Oscarr updates improves as a side effect, since changing one page no longer invalidates everything.","descFr":"Les pages sont récupérées au moment où vous les ouvrez au lieu d''embarquer presque toute l''application dès le premier affichage : le téléchargement critique passe de 277 ko à 242 ko compressés. L''accueil et la connexion restent disponibles immédiatement. Le cache du navigateur entre deux mises à jour s''en trouve amélioré, puisque modifier une page n''invalide plus l''ensemble."},{"type":"fix","titleEn":"The update banner no longer points at an older version","titleFr":"La bannière de mise à jour ne renvoie plus vers une version antérieure","descEn":"The check compared version numbers as plain text, so any difference, including an older published version, was announced as an update. Versions are now compared as versions.","descFr":"La vérification comparait les numéros de version comme du texte : tout écart, y compris une version publiée plus ancienne, était annoncé comme une mise à jour. Les versions sont désormais comparées en tant que versions."},{"type":"other","titleEn":"Smaller fixes and groundwork","titleFr":"Correctifs et travaux de fond","descEn":"The instance API key is encrypted like every other credential. NSFW keywords are cached instead of being re-read on every search. The dashboard widget picker gained keyboard navigation and proper focus handling. Folder routing rules, multi-instance ownership and quality-option changes got dedicated automated coverage, and Oscarr now carries 186 automated tests, up from 147. Dependency updates arrive weekly, grouped, with a cooldown before a freshly published version is proposed, and CI rejects any critical advisory.","descFr":"La clé d''API de l''instance est chiffrée comme tout autre identifiant. Les mots-clés NSFW sont mis en cache au lieu d''être relus à chaque recherche. Le sélecteur de widgets du tableau de bord gagne la navigation au clavier et une gestion correcte du focus. Les règles de routage de dossiers, la propriété multi-instances et les changements d''option de qualité disposent de tests automatisés dédiés, et Oscarr compte désormais 186 tests automatisés contre 147. Les mises à jour de dépendances arrivent chaque semaine, groupées, avec un délai avant qu''une version fraîchement publiée soit proposée, et la CI rejette toute alerte critique."}]')
ON CONFLICT ("version") DO NOTHING;
